package gh.giftedlabs.pos.dto;

import gh.giftedlabs.pos.rules.PaymentMethod;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;

import java.math.BigDecimal;
import java.util.List;
import java.util.UUID;

/**
 * A sale being completed — FR-POS, FR-PAY, BR-7.
 *
 * <p>{@code id} and each payment's {@code id} are generated by the client. That
 * is BR-7: submitting the same sale twice must record it once and return the
 * original, and only a client-chosen key makes a retry recognisable.
 *
 * <p>Line totals are <em>not</em> accepted from the client. The server prices
 * the sale from the catalogue and its own arithmetic, because a total the
 * browser computed is a total the browser could have got wrong — or changed.
 *
 * <p>Discounts arrive at two levels, which FR-POS-10 asks for separately: off
 * one line, and off the whole cart. The cart concession is stated once here
 * rather than pre-spread by the browser, so the server decides how it lands on
 * the lines and the ceiling is measured against what was actually conceded.
 */
public record SaleRequest(

        @NotNull(message = "A sale needs a client-generated id") UUID id,
        @NotNull(message = "Choose the branch") UUID outletId,
        UUID terminalId,

        UUID customerId,
        @Size(max = 200) String customerName,
        @Size(max = 40) String customerPhone,

        @NotEmpty(message = "A sale needs at least one line")
        @Valid List<Line> items,

        /**
         * FR-POS-10: a concession off the whole cart, as a percentage.
         *
         * <p>Mutually exclusive with {@link #cartDiscount}. Sending both is
         * refused rather than reconciled — two statements of the same
         * concession that disagree have no correct interpretation.
         */
        @PositiveOrZero @DecimalMax(value = "100.00", message = "A cart discount cannot exceed 100%")
        BigDecimal cartDiscountPercent,

        /** FR-POS-10: the same concession stated as pesewas off the cart. */
        @PositiveOrZero Long cartDiscount,

        /** FR-POS-10: required when the cart discount passes the seller's ceiling. */
        UUID cartDiscountApprovedBy,

        /**
         * The approver's PIN for the cart discount — BR-10/FR-POS-10.
         *
         * <p>An approver id alone is a claim the browser can make up; the PIN is
         * what proves the named manager actually authorised this. The server
         * honours {@link #cartDiscountApprovedBy} only when this PIN matches it.
         */
        String cartDiscountApprovalPin,

        @NotEmpty(message = "A sale needs at least one payment")
        @Valid List<PaymentLine> payments) {

    /** Back-compat: a sale with no cart-discount approval PIN. */
    public SaleRequest(UUID id, UUID outletId, UUID terminalId, UUID customerId, String customerName,
                       String customerPhone, List<Line> items, BigDecimal cartDiscountPercent,
                       Long cartDiscount, UUID cartDiscountApprovedBy, List<PaymentLine> payments) {
        this(id, outletId, terminalId, customerId, customerName, customerPhone, items,
                cartDiscountPercent, cartDiscount, cartDiscountApprovedBy, null, payments);
    }

    public record Line(
            @NotNull UUID productId,
            @NotBlank @Size(max = 60) String selectedUnit,
            @NotNull @Positive BigDecimal conversionFactor,
            @NotNull @Positive(message = "Enter a quantity greater than zero") BigDecimal quantity,

            /** What the line was actually sold at, in major units. */
            @NotNull @PositiveOrZero BigDecimal unitPrice,

            /** BR-11: pesewas off this line. */
            @PositiveOrZero Long discount,

            /** BR-10: required when unitPrice is below the product's floor. */
            UUID floorApprovedBy,

            /** FR-POS-10: required when the discount passes the seller's ceiling. */
            UUID discountApprovedBy,

            /** The floor approver's PIN — BR-10. Proves {@link #floorApprovedBy} consented. */
            String floorApprovalPin,

            /** The discount approver's PIN — FR-POS-10. Proves {@link #discountApprovedBy} consented. */
            String discountApprovalPin) {

        /** Back-compat: a line with no approval PINs. */
        public Line(UUID productId, String selectedUnit, BigDecimal conversionFactor, BigDecimal quantity,
                    BigDecimal unitPrice, Long discount, UUID floorApprovedBy, UUID discountApprovedBy) {
            this(productId, selectedUnit, conversionFactor, quantity, unitPrice, discount,
                    floorApprovedBy, discountApprovedBy, null, null);
        }
    }

    public record PaymentLine(
            @NotNull(message = "Each payment needs a client-generated id") UUID id,
            @NotNull PaymentMethod method,
            @NotNull @Positive(message = "A payment must be more than zero") Long amount,
            @Size(max = 60) String provider,
            @Size(max = 120) String reference) {
    }
}
